begin;
do $$ declare a uuid:='29000000-0000-4000-8000-000000000091';w uuid:='29000000-0000-4000-8000-000000000092';r uuid;v bigint;i int;t0 timestamptz;elapsed numeric; begin
insert into auth.users(id) values(a) on conflict do nothing;insert into public.workspaces(id,owner_id,slug,name,status) values(w,a,'m029-perf','M029 perf','active') on conflict do nothing;insert into public.workspace_members(workspace_id,user_id,role,status) values(w,a,'owner','active') on conflict do nothing;insert into public.account_personal_workspaces(user_id,workspace_id) values(a,w) on conflict do nothing;perform set_config('request.jwt.claim.role','authenticated',true);perform set_config('request.jwt.claim.sub',a::text,true);
t0:=clock_timestamp();for i in 1..50 loop select object_id,object_version into r,v from public.save_personal_operational_record_v2(null,'CONTENT','Perf '||i,jsonb_build_object('status','DRAFT'),'DRAFT',null,'m029:perf:create:'||i);end loop;elapsed:=extract(epoch from clock_timestamp()-t0)*1000;if elapsed>10000 then raise exception 'm029_performance_create_budget_exceeded:%',elapsed;end if;
t0:=clock_timestamp();perform public.save_personal_operational_record_v2(r,'CONTENT','Perf updated',jsonb_build_object('status','DRAFT'),'DRAFT',v,'m029:perf:update');elapsed:=extract(epoch from clock_timestamp()-t0)*1000;if elapsed>5000 then raise exception 'm029_performance_update_budget_exceeded:%',elapsed;end if;
t0:=clock_timestamp();perform public.save_canonical_domain_draft('CONTENT',r,0,v+1,jsonb_build_object('body','durable'),'PC');elapsed:=extract(epoch from clock_timestamp()-t0)*1000;if elapsed>5000 then raise exception 'm029_performance_draft_budget_exceeded:%',elapsed;end if;end $$;
select jsonb_build_object('result','M029_PERFORMANCE_VALIDATION_PASS','synthetic_rows',50,'transaction_rolled_back',true) verification;rollback;
